// Regression fixture for #61 — a dependency registering its own loader hook AHEAD of
// capwall's. Node runs the most recently registered hook first, and the synchronous
// `registerHooks` chain runs entirely before the asynchronous `register` chain capwall lives
// in, so a hook installed here short-circuits mediated specifiers to the real `node:` URL
// before capwall's resolve is ever consulted — process-wide, for every package.
//
// EXTENDED FOR #181, which is #61 restored through the shim itself. The gate used to be a wrapper
// the `node:module` shim's `get` trap returned for the two keys `register`/`registerHooks`, and
// `node:module` hands out other own keys that reach the same two functions — starting with
// `Module`, its own legacy self-reference. So this fixture no longer asks for the named export
// alone: it walks every route a dependency actually has, and a gate that covers one spelling and
// not another fails here rather than in production.
//
//   named-export        `import { registerHooks } from "node:module"`   — what #61 gated
//   Module-class        `import { Module } from "node:module"`          — the same object (#181)
//   require-Module      `require("node:module").Module`                 — ditto, from CJS
//   module-constructor  every CJS module already holds the class        — no `require` at all
//   getBuiltinModule    `process.getBuiltinModule("node:module")`       — around the shim entirely
//
// Inert per AGENTS.md § 8: every hook body below only rewrites a specifier string. This fixture
// reads nothing, spawns nothing and sends nothing; esm-victim-dep supplies the observable effect.
import { createRequire } from "node:module";

const requireCjs = createRequire(import.meta.url);

/** Rewrites mediated specifiers straight to the raw builtin URL. */
function jackingResolve(spec, ctx, next) {
  if (["fs", "node:fs", "child_process", "node:child_process"].includes(spec)) {
    return { url: spec.startsWith("node:") ? spec : "node:" + spec, shortCircuit: true, format: "builtin" };
  }
  return next(spec, ctx);
}

/**
 * How to reach the registration functions. Each entry returns `[fn, receiver]` — a different path
 * to what should be the same, gated function object.
 */
const ROUTES = {
  async "named-export"(api) {
    const mod = await import("node:module");
    return [mod[api], mod];
  },
  async "Module-class"(api) {
    const { Module } = await import("node:module");
    return [Module && Module[api], Module];
  },
  "require-Module"(api) {
    const Module = requireCjs("node:module").Module;
    return [Module && Module[api], Module];
  },
  "module-constructor"(api) {
    const Module = requireCjs("./ctor.cjs").moduleConstructor();
    return [Module && Module[api], Module];
  },
  "getBuiltinModule"(api) {
    const mod = process.getBuiltinModule && process.getBuiltinModule("node:module");
    return [mod && mod[api], mod];
  },
};

/** `register` takes a specifier + parent URL; `registerHooks` takes an object of hooks. */
function argsFor(api) {
  return api === "registerHooks"
    ? [{ resolve: jackingResolve }]
    : ["data:text/javascript,export const resolve=(s,c,n)=>n(s,c);", import.meta.url];
}

/** Attempts one (route, api) pair; returns `"<route>:<api>:<OUTCOME>"`. */
async function tryRegister(route, api) {
  const label = `${route}:${api}`;
  let fn;
  let receiver;
  try {
    [fn, receiver] = await ROUTES[route](api);
  } catch (err) {
    return `${label}:UNREACHABLE:${err && err.name}`;
  }
  if (typeof fn !== "function") return `${label}:UNSUPPORTED`;
  try {
    Reflect.apply(fn, receiver, argsFor(api));
    return `${label}:REGISTERED`;
  } catch (err) {
    return err && err.name === "CapabilityError"
      ? `${label}:BLOCKED:${err.pkg}`
      : `${label}:ERR:${err && err.code}`;
  }
}

export async function run() {
  const out = [];
  for (const route of Object.keys(ROUTES)) {
    for (const api of ["registerHooks", "register"]) out.push(await tryRegister(route, api));
  }
  // Only NOW pull in the innocent third package, so its static `import * as fs from "node:fs"`
  // is resolved after any hook the lines above managed to install.
  const victim = await import("esm-victim-dep");
  out.push(`victim:${victim.read()}`);
  return out;
}
